assert len({s[0] for s in sources})==len(sources)
records=[]
for sid,title,author,year,url,reason,level,lic in sources:
  records.append({'source_id':sid,'title':title,'author_or_editor':author,'publication_year_or_edition':year,'canonical_url':url,'research_scope':reason,'verification_status':level,'full_work_read':False,'rights_or_reuse':lic,'source_type':'publisher_or_maintainer_page' if level=='landing_page_checked' else 'accessible_article_or_standard_section','checked_on':'2026-11-08','unresolved':'Exact edition, chapter passage, rights, and academic review to confirm per claim.'})
(root/'V5_EXTERN_RECHERCHIERTE_QUELLEN.json').write_text(json.dumps(records,ensure_ascii=False,indent=2),encoding='utf-8')
with (root/'V5_EXTERN_RECHERCHIERTE_QUELLEN.csv').open('w',encoding='utf-8',newline='') as f:
 w=csv.DictWriter(f,fieldnames=records[0].keys());w.writeheader();w.writerows(records)
with (root/'LESEROUTE_UND_PRIORITAET.md').open('w',encoding='utf-8') as f:
 f.write('# V5 Recherchequellen: Lesestatus und nächste Schritte\n\n')
 f.write('Die folgenden Nachweise sind im Web am 8.11.2026 konsultiert worden. `landing_page_checked` heißt ausdrücklich **nicht**, dass das Buch vollständig gelesen wurde. Die 77 V4-Datensätze bleiben im Archiv, sie werden nicht als neu überprüft gezählt.\n\n')
 for s in records:
  f.write(f"- **[{s['source_id']}] {s['title']}** – [{s['canonical_url']}]({s['canonical_url']}) · {s['verification_status']} · {s['research_scope']}. Rechte: {s['rights_or_reuse']}.\n")
 f.write('\n## Priorität P0\n\nRead-only Quellenabgleich, Open-Music-Theory-Lizenz je Textbestandteil, genauer DCML-Parser-/Datenvertrag, originaler ChoCo-Subdatensatz-Lizenzbaum, `music21`-Corpus-Rechte.\n\n## Priorität P1\n\nCaplin, Nobile, Gjerdingen, Sanguinetti, Cohn, Lerdahl, Huron auf rechtmäßig verfügbare Volltexte und exakte Abschnitte prüfen. Danach konkrete Claims mit Seiten-/Kapitelstellen belegen.\n\n## Priorität P2\n\nMaqam/Raga/afrikanische Musik nur in Zusammenarbeit mit traditionsspezifisch qualifizierten Quellen/Reviewer als produktive Analysesysteme aufnehmen.\n')
print('Wrote',len(records),'web-evidence source records')
